379	  private boolean offsetCanvas(Canvas canvas, DocumentData documentData, int lineIndex, float lineWidth) {
380	    PointF position = documentData.boxPosition;
381	    PointF size = documentData.boxSize;
382	    float dpScale = Utils.dpScale();
383	    float lineStartY = position == null ? 0f : documentData.lineHeight * dpScale + position.y;
384	    float lineOffset = (lineIndex * documentData.lineHeight * dpScale) + lineStartY;
385	    if (lottieDrawable.getClipTextToBoundingBox() && size != null && position != null && lineOffset >= position.y + size.y + documentData.size) {
386	      return false;
387	    }
388	    float lineStart = position == null ? 0f : position.x;
389	    float boxWidth = size == null ? 0f : size.x;
390	    switch (documentData.justification) {
391	      case LEFT_ALIGN:
392	        canvas.translate(lineStart, lineOffset);
393	        break;
394	      case RIGHT_ALIGN:
395	        canvas.translate(lineStart + boxWidth - lineWidth, lineOffset);
396	        break;
397	      case CENTER:
398	        canvas.translate(lineStart + boxWidth / 2f - lineWidth / 2f, lineOffset);
399	        break;
400	    }
401	    return true;
402	  }
