432	  private void drawFontTextLine(String text,
433	      DocumentData documentData,
434	      Canvas canvas,
435	      float tracking,
436	      int characterIndexAtStartOfLine,
437	      int parentAlpha) {
438	    charStrings.clear();
439	    for (int i = 0; i < text.length(); ) {
440	      String charString = codePointToString(text, i);
441	      charStrings.add(charString);
442	      i += charString.length();
443	    }
444	
445	    for (int i = 0; i < charStrings.size(); ) {
446	      charStringBuilder.setLength(0);
447	      charStringBuilder.append(charStrings.get(i));
448	      int nextIndex = i + 1;
449	      while (nextIndex < charStrings.size()) {
450	        String nextCharString = charStrings.get(nextIndex);
451	        if (isJoiningRightToLeft(nextCharString)) {
452	          // We insert at the front explicitly, string builder will actually add it to the end visually since it is rtl
453	          charStringBuilder.insert(0, nextCharString);
454	          nextIndex++;
455	        } else {
456	          break;
457	        }
458	      }
459	
460	      String charString = charStringBuilder.toString();
461	      drawCharacterFromFont(charString, documentData, canvas, characterIndexAtStartOfLine + i, parentAlpha);
462	      float charWidth = fillPaint.measureText(charString);
463	      float tx = charWidth + tracking;
464	      canvas.translate(tx, 0);
465	
466	      i = nextIndex;
467	    }
468	  }
