470	  /**
471	   * Transform string stored in logical order to visual order.
472	   * For example, if an RTL language is stored as qwert in memory, it will become trewq,
473	   * so we can keep the logic of drawing each character from left to right afterward.
474	   *
475	   * @param text the original string
476	   * @return the text in visual order, written from left to right
477	   */
478	  private String reorderLineVisually(String text) {
479	    Bidi bidi = new Bidi(text, Bidi.DIRECTION_DEFAULT_LEFT_TO_RIGHT);
480	    int runCount = bidi.getRunCount();
481	    byte[] runLevels = new byte[runCount];
482	    Integer[] runs = new Integer[runCount];
483	    for (int i = 0; i < runCount; i++) {
484	      runLevels[i] = (byte) bidi.getRunLevel(i);
485	      runs[i] = i;
486	    }
487	    Bidi.reorderVisually(runLevels, 0, runs, 0, runCount);
488	
489	    reorderingStringBuilder.setLength(0);
490	    for (int i = 0; i < runCount; i++) {
491	      int originalIndex = runs[i];
492	      int runStart = bidi.getRunStart(originalIndex);
493	      int runLimit = bidi.getRunLimit(originalIndex);
494	      // Even run level means LTR, odd means RTL
495	      int runLevel = bidi.getRunLevel(originalIndex);
496	
497	      String word = text.substring(runStart, runLimit);
498	      if ((runLevel & 1) == 0) {
499	        reorderingStringBuilder.append(word);
500	      } else {
501	        reversingStringBuilder.setLength(0);
502	        for (int j = 0; j < word.length();) {
503	          String charString = codePointToString(word, j);
504	          reversingStringBuilder.insert(0, charString);
505	          j += charString.length();
506	        }
507	        reorderingStringBuilder.append(reversingStringBuilder);
508	      }
509	    }
510	
511	    return reorderingStringBuilder.toString();
512	  }
