655	  private List<ContentGroup> getContentsForCharacter(FontCharacter character) {
656	    if (contentsForCharacter.containsKey(character)) {
657	      return contentsForCharacter.get(character);
658	    }
659	    List<ShapeGroup> shapes = character.getShapes();
660	    int size = shapes.size();
661	    List<ContentGroup> contents = new ArrayList<>(size);
662	    for (int i = 0; i < size; i++) {
