670	  private String codePointToString(String text, int startIndex) {
671	    int firstCodePoint = text.codePointAt(startIndex);
672	    int firstCodePointLength = Character.charCount(firstCodePoint);
673	    int key = firstCodePoint;
674	    int index = startIndex + firstCodePointLength;
675	    while (index < text.length()) {
676	      int nextCodePoint = text.codePointAt(index);
677	      if (!isModifier(nextCodePoint)) {
678	        break;
679	      }
680	      int nextCodePointLength = Character.charCount(nextCodePoint);
681	      index += nextCodePointLength;
682	      key = key * 31 + nextCodePoint;
683	    }
684	
685	    if (codePointCache.containsKey(key)) {
686	      return codePointCache.get(key);
687	    }
688	
689	    stringBuilder.setLength(0);
690	    for (int i = startIndex; i < index; ) {
691	      int codePoint = text.codePointAt(i);
692	      stringBuilder.appendCodePoint(codePoint);
693	      i += Character.charCount(codePoint);
694	    }
695	    String str = stringBuilder.toString();
696	    codePointCache.put(key, str);
697	    return str;
698	  }
