700	  private boolean isModifier(int codePoint) {
701	    int type = Character.getType(codePoint);
702	    return type == Character.FORMAT ||
703	        type == Character.MODIFIER_SYMBOL ||
704	        type == Character.NON_SPACING_MARK ||
705	        type == Character.OTHER_SYMBOL ||
706	        type == Character.DIRECTIONALITY_NONSPACING_MARK ||
707	        type == Character.SURROGATE;
708	  }
