712	   * This is used for determining if we should render a group of characters together,
713	   * and we will pass them to the renderer to pick the correct joining glyph.
714	   *
715	   * @param stringChar a string that preferably contains only one visual character
716	   * @return true if any character in the input is joining, and is written from right to left
717	   */
718	  private boolean isJoiningRightToLeft(String stringChar) {
719	    for (int i = 0; i < stringChar.length(); i++) {
720	      int codePoint = stringChar.codePointAt(i);
721	      if (Character.getDirectionality(codePoint) == Character.DIRECTIONALITY_RIGHT_TO_LEFT_ARABIC) {
722	        return true;
723	      }
724	    }
725	    return false;
726	  }
