12	public class SplitDimensionPathKeyframeAnimation extends BaseKeyframeAnimation<PointF, PointF> {
13	  private final PointF point = new PointF();
14	  private final PointF pointWithCallbackValues = new PointF();
15	  private final BaseKeyframeAnimation<Float, Float> xAnimation;
16	  private final BaseKeyframeAnimation<Float, Float> yAnimation;
17	
18	  @Nullable protected LottieValueCallback<Float> xValueCallback;
19	  @Nullable protected LottieValueCallback<Float> yValueCallback;
20	
21	
22	  public SplitDimensionPathKeyframeAnimation(
23	      BaseKeyframeAnimation<Float, Float> xAnimation,
24	      BaseKeyframeAnimation<Float, Float> yAnimation) {
25	    super(Collections.<Keyframe<PointF>>emptyList());
26	
27	    this.xAnimation = xAnimation;
28	    this.yAnimation = yAnimation;
29	    // We need to call an initial setProgress so point gets set with the initial value.
30	    setProgress(getProgress());
31	  }
32	
33	  public void setXValueCallback(@Nullable LottieValueCallback<Float> xValueCallback) {
34	    if (this.xValueCallback != null) {
35	      this.xValueCallback.setAnimation(null);
36	    }
37	    this.xValueCallback = xValueCallback;
38	    if (xValueCallback != null) {
39	      xValueCallback.setAnimation(this);
40	    }
41	  }
42	
43	  public void setYValueCallback(@Nullable LottieValueCallback<Float> yValueCallback) {
44	    if (this.yValueCallback != null) {
45	      this.yValueCallback.setAnimation(null);
46	    }
47	    this.yValueCallback = yValueCallback;
48	    if (yValueCallback != null) {
49	      yValueCallback.setAnimation(this);
50	    }
51	  }
52	
53	  @Override public void setProgress(float progress) {
54	    xAnimation.setProgress(progress);
55	    yAnimation.setProgress(progress);
56	    point.set(xAnimation.getValue(), yAnimation.getValue());
57	    for (int i = 0; i < listeners.size(); i++) {
58	      listeners.get(i).onValueChanged();
59	    }
60	  }
61	
62	  @Override public PointF getValue() {
63	    return getValue(null, 0);
64	  }
65	
66	  @Override PointF getValue(Keyframe<PointF> keyframe, float keyframeProgress) {
67	    Float xCallbackValue = null;
68	    Float yCallbackValue = null;
69	
70	    if (xValueCallback != null) {
71	      Keyframe<Float> xKeyframe = xAnimation.getCurrentKeyframe();
72	      if (xKeyframe != null) {
73	        Float endFrame = xKeyframe.endFrame;
74	        xCallbackValue =
75	            xValueCallback.getValueInternal(xKeyframe.startFrame,
76	                endFrame == null ? xKeyframe.startFrame : endFrame,
77	                xKeyframe.startValue,
78	                xKeyframe.endValue,
79	                xAnimation.getInterpolatedCurrentKeyframeProgress(),
80	                xAnimation.getLinearCurrentKeyframeProgress(),
81	                xAnimation.getProgress());
82	      }
83	    }
84	    if (yValueCallback != null) {
85	      Keyframe<Float> yKeyframe = yAnimation.getCurrentKeyframe();
86	      if (yKeyframe != null) {
87	        Float endFrame = yKeyframe.endFrame;
88	        yCallbackValue =
89	            yValueCallback.getValueInternal(yKeyframe.startFrame,
90	                endFrame == null ? yKeyframe.startFrame : endFrame,
91	                yKeyframe.startValue,
92	                yKeyframe.endValue,
93	                yAnimation.getInterpolatedCurrentKeyframeProgress(),
94	                yAnimation.getLinearCurrentKeyframeProgress(),
95	                yAnimation.getProgress());
96	      }
97	    }
98	
99	    if (xCallbackValue == null) {
100	      pointWithCallbackValues.set(point.x, 0f);
101	    } else {
102	      pointWithCallbackValues.set(xCallbackValue, 0f);
103	    }
104	
105	    if (yCallbackValue == null) {
106	      pointWithCallbackValues.set(pointWithCallbackValues.x, point.y);
107	    } else {
108	      pointWithCallbackValues.set(pointWithCallbackValues.x, yCallbackValue);
109	    }
110	
111	    return pointWithCallbackValues;
112	  }
113	}
