2	
3	import android.graphics.Color;
4	
5	import com.airbnb.lottie.model.content.GradientColor;
6	import com.airbnb.lottie.parser.moshi.JsonReader;
7	import com.airbnb.lottie.utils.GammaEvaluator;
8	import com.airbnb.lottie.utils.MiscUtils;
9	
10	import java.io.IOException;
11	import java.util.ArrayList;
12	import java.util.Arrays;
13	import java.util.List;
14	
15	public class GradientColorParser implements com.airbnb.lottie.parser.ValueParser<GradientColor> {
16	  /**
17	   * The number of colors if it exists in the json or -1 if it doesn't (legacy bodymovin)
18	   */
19	  private int colorPoints;
20	
21	  public GradientColorParser(int colorPoints) {
22	    this.colorPoints = colorPoints;
23	  }
24	
25	  /**
26	   * Both the color stops and opacity stops are in the same array.
27	   * There are {@link #colorPoints} colors sequentially as:
28	   * [
29	   * ...,
30	   * position,
31	   * red,
32	   * green,
33	   * blue,
34	   * ...
35	   * ]
36	   * <p>
37	   * The remainder of the array is the opacity stops sequentially as:
38	   * [
39	   * ...,
40	   * position,
41	   * opacity,
42	   * ...
43	   * ]
44	   */
45	  @Override
46	  public GradientColor parse(JsonReader reader, float scale)
47	      throws IOException {
48	    List<Float> array = new ArrayList<>();
49	    // The array was started by Keyframe because it thought that this may be an array of keyframes
50	    // but peek returned a number so it considered it a static array of numbers.
51	    boolean isArray = reader.peek() == JsonReader.Token.BEGIN_ARRAY;
52	    if (isArray) {
53	      reader.beginArray();
54	    }
55	    while (reader.hasNext()) {
56	      array.add((float) reader.nextDouble());
57	    }
58	    if (array.size() == 4 && array.get(0) == 1f) {
59	      // If a gradient color only contains one color at position 1, add a second stop with the same
60	      // color at position 0. Android's LinearGradient shader requires at least two colors.
61	      // https://github.com/airbnb/lottie-android/issues/1967
62	      array.set(0, 0f);
63	      array.add(1f);
64	      array.add(array.get(1));
65	      array.add(array.get(2));
66	      array.add(array.get(3));
67	      colorPoints = 2;
68	    }
69	    if (isArray) {
70	      reader.endArray();
71	    }
72	    if (colorPoints == -1) {
73	      colorPoints = array.size() / 4;
74	    }
75	
76	    float[] positions = new float[colorPoints];
77	    int[] colors = new int[colorPoints];
78	
79	    int r = 0;
80	    int g = 0;
81	    for (int i = 0; i < colorPoints * 4; i++) {
82	      int colorIndex = i / 4;
83	      double value = array.get(i);
84	      switch (i % 4) {
85	        case 0:
86	          // Positions should monotonically increase. If they don't, it can cause rendering problems on some phones.
87	          // https://github.com/airbnb/lottie-android/issues/1675
88	          if (colorIndex > 0 && positions[colorIndex - 1] >= (float) value) {
89	            positions[colorIndex] = (float) value + 0.01f;
90	          } else {
91	            positions[colorIndex] = (float) value;
92	          }
93	          break;
94	        case 1:
95	          r = (int) (value * 255);
96	          break;
97	        case 2:
98	          g = (int) (value * 255);
99	          break;
100	        case 3:
101	          int b = (int) (value * 255);
102	          colors[colorIndex] = Color.argb(255, r, g, b);
103	          break;
104	      }
105	    }
106	
107	    GradientColor gradientColor = new GradientColor(positions, colors);
108	    gradientColor = addOpacityStopsToGradientIfNeeded(gradientColor, array);
109	    return gradientColor;
110	  }
111	
112	  /**
113	   * This cheats a little bit.
114	   * Opacity stops can be at arbitrary intervals independent of color stops.
115	   * This uses the existing color stops and modifies the opacity at each existing color stop
116	   * based on what the opacity would be.
117	   * <p>
118	   * This should be a good approximation is nearly all cases. However, if there are many more
119	   * opacity stops than color stops, information will be lost.
120	   */
121	  private GradientColor addOpacityStopsToGradientIfNeeded(GradientColor gradientColor, List<Float> array) {
122	    int startIndex = colorPoints * 4;
123	    if (array.size() <= startIndex) {
124	      return gradientColor;
125	    }
126	
127	    // When there are opacity stops, we create a merged list of color stops and opacity stops.
128	    // For a given color stop, we linearly interpolate the opacity for the two opacity stops around it.
129	    // For a given opacity stop, we linearly interpolate the color for the two color stops around it.
130	    float[] colorStopPositions = gradientColor.getPositions();
131	    int[] colorStopColors = gradientColor.getColors();
132	
133	    int opacityStops = (array.size() - startIndex) / 2;
134	    float[] opacityStopPositions = new float[opacityStops];
135	    float[] opacityStopOpacities = new float[opacityStops];
136	
137	    for (int i = startIndex, j = 0; i < array.size(); i++) {
138	      if (i % 2 == 0) {
139	        opacityStopPositions[j] = array.get(i);
140	      } else {
141	        opacityStopOpacities[j] = array.get(i);
142	        j++;
143	      }
144	    }
145	
146	    // Pre-SKIA (Oreo) devices render artifacts when there is two stops in the same position.
147	    // As a result, we have to de-dupe the merge color and opacity stop positions.
148	    float[] newPositions = mergeUniqueElements(gradientColor.getPositions(), opacityStopPositions);
149	    int newColorPoints = newPositions.length;
150	    int[] newColors = new int[newColorPoints];
151	
152	    for (int i = 0; i < newColorPoints; i++) {
153	      float position = newPositions[i];
154	      int colorStopIndex = Arrays.binarySearch(colorStopPositions, position);
155	      int opacityIndex = Arrays.binarySearch(opacityStopPositions, position);
156	      if (colorStopIndex < 0 || opacityIndex > 0) {
157	        // This is a stop derived from an opacity stop.
158	        if (opacityIndex < 0) {
159	          // The formula here is derived from the return value for binarySearch. When an item isn't found, it returns -insertionPoint - 1.
160	          opacityIndex = -(opacityIndex + 1);
161	        }
162	        newColors[i] = getColorInBetweenColorStops(position, opacityStopOpacities[opacityIndex], colorStopPositions, colorStopColors);
163	      } else {
164	        // This os a step derived from a color stop.
165	        newColors[i] = getColorInBetweenOpacityStops(position, colorStopColors[colorStopIndex], opacityStopPositions, opacityStopOpacities);
166	      }
167	    }
168	    return new GradientColor(newPositions, newColors);
169	  }
170	
171	  int getColorInBetweenColorStops(float position, float opacity, float[] colorStopPositions, int[] colorStopColors) {
172	    if (colorStopColors.length < 2 || position == colorStopPositions[0]) {
173	      return colorStopColors[0];
174	    }
175	    for (int i = 1; i < colorStopPositions.length; i++) {
176	      float colorStopPosition = colorStopPositions[i];
177	      if (colorStopPosition < position && i != colorStopPositions.length - 1) {
178	        continue;
179	      }
180	      if (i == colorStopPositions.length - 1 && position >= colorStopPosition) {
181	        return Color.argb(
182	            (int) (opacity * 255),
183	            Color.red(colorStopColors[i]),
184	            Color.green(colorStopColors[i]),
185	            Color.blue(colorStopColors[i])
186	        );
187	      }
188	      // We found the position in which position is between i - 1 and i.
189	      float distanceBetweenColors = colorStopPositions[i] - colorStopPositions[i - 1];
190	      float distanceToLowerColor = position - colorStopPositions[i - 1];
191	      float percentage = distanceToLowerColor / distanceBetweenColors;
192	
193	      int upperColor = colorStopColors[i];
194	      int lowerColor = colorStopColors[i - 1];
195	      int intermediateColor = GammaEvaluator.evaluate(percentage, lowerColor, upperColor);
196	
197	      int a = (int) (opacity * 255);
198	      int r = Color.red(intermediateColor);
199	      int g = Color.green(intermediateColor);
200	      int b = Color.blue(intermediateColor);
201	
202	      return Color.argb(a, r, g, b);
203	    }
204	    throw new IllegalArgumentException("Unreachable code.");
205	  }
206	
207	  private int getColorInBetweenOpacityStops(float position, int color, float[] opacityStopPositions, float[] opacityStopOpacities) {
208	    if (opacityStopOpacities.length < 2 || position <= opacityStopPositions[0]) {
209	      int a = (int) (opacityStopOpacities[0] * 255);
210	      int r = Color.red(color);
211	      int g = Color.green(color);
212	      int b = Color.blue(color);
213	      return Color.argb(a, r, g, b);
214	    }
215	    for (int i = 1; i < opacityStopPositions.length; i++) {
216	      float opacityStopPosition = opacityStopPositions[i];
217	      if (opacityStopPosition < position && i != opacityStopPositions.length - 1) {
218	        continue;
219	      }
220	      final int a;
221	      if (opacityStopPosition <= position) {
222	        a = (int) (opacityStopOpacities[i] * 255);
223	      } else {
224	        // We found the position in which position in between i - 1 and i.
225	        float distanceBetweenOpacities = opacityStopPositions[i] - opacityStopPositions[i - 1];
226	        float distanceToLowerOpacity = position - opacityStopPositions[i - 1];
227	        float percentage = distanceToLowerOpacity / distanceBetweenOpacities;
228	        a = (int) (MiscUtils.lerp(opacityStopOpacities[i - 1], opacityStopOpacities[i], percentage) * 255);
229	      }
230	      int r = Color.red(color);
231	      int g = Color.green(color);
232	      int b = Color.blue(color);
233	      return Color.argb(a, r, g, b);
234	    }
235	    throw new IllegalArgumentException("Unreachable code.");
236	  }
237	
238	  /**
239	   * Takes two sorted float arrays and merges their elements while removing duplicates.
240	   */
241	  protected static float[] mergeUniqueElements(float[] arrayA, float[] arrayB) {
242	    if (arrayA.length == 0) {
243	      return arrayB;
244	    } else if (arrayB.length == 0) {
245	      return arrayA;
246	    }
247	
248	    int aIndex = 0;
249	    int bIndex = 0;
250	    int numDuplicates = 0;
251	    // This will be the merged list but may be longer than what is needed if there are duplicates.
252	    // If there are, the 0 elements at the end need to be truncated.
253	    float[] mergedNotTruncated = new float[arrayA.length + arrayB.length];
254	    for (int i = 0; i < mergedNotTruncated.length; i++) {
255	      final float a = aIndex < arrayA.length ? arrayA[aIndex] : Float.NaN;
256	      final float b = bIndex < arrayB.length ? arrayB[bIndex] : Float.NaN;
257	
258	      if (Float.isNaN(b) || a < b) {
259	        mergedNotTruncated[i] = a;
260	        aIndex++;
261	      } else if (Float.isNaN(a) || b < a) {
262	        mergedNotTruncated[i] = b;
263	        bIndex++;
264	      } else {
265	        mergedNotTruncated[i] = a;
266	        aIndex++;
267	        bIndex++;
268	        numDuplicates++;
269	      }
270	    }
271	
272	    if (numDuplicates == 0) {
273	      return mergedNotTruncated;
274	    }
275	
276	    return Arrays.copyOf(mergedNotTruncated, mergedNotTruncated.length - numDuplicates);
277	  }
278	}
