297	  private void drawGlyphTextLine(String text, DocumentData documentData,
298	      Font font, Canvas canvas, float parentScale, float fontScale, float tracking, int parentAlpha) {
299	    for (int i = 0; i < text.length(); i++) {
300	      char c = text.charAt(i);
301	      int characterHash = FontCharacter.hashFor(c, font.getFamily(), font.getStyle());
302	      FontCharacter character = composition.getCharacters().get(characterHash);
303	      if (character == null) {
304	        // Something is wrong. Potentially, they didn't export the text as a glyph.
305	        continue;
306	      }
307	      drawCharacterAsGlyph(character, fontScale, documentData, canvas, i, parentAlpha);
308	      float tx = (float) character.getWidth() * fontScale * Utils.dpScale() + tracking;
309	      canvas.translate(tx, 0);
310	    }
311	  }
