26	public class RepeaterContent implements DrawingContent, PathContent, GreedyContent,
27	    BaseKeyframeAnimation.AnimationListener, KeyPathElementContent {
28	  private final Matrix matrix = new Matrix();
29	  private final Path path = new Path();
30	
31	  private final LottieDrawable lottieDrawable;
32	  private final BaseLayer layer;
33	  private final String name;
34	  private final boolean hidden;
35	  private final BaseKeyframeAnimation<Float, Float> copies;
36	  private final BaseKeyframeAnimation<Float, Float> offset;
37	  private final TransformKeyframeAnimation transform;
