40	
41	  public RepeaterContent(LottieDrawable lottieDrawable, BaseLayer layer, Repeater repeater) {
42	    this.lottieDrawable = lottieDrawable;
43	    this.layer = layer;
44	    name = repeater.getName();
45	    this.hidden = repeater.isHidden();
46	    copies = repeater.getCopies().createAnimation();
47	    layer.addAnimation(copies);
48	    copies.addUpdateListener(this);
49	
50	    offset = repeater.getOffset().createAnimation();
51	    layer.addAnimation(offset);
52	    offset.addUpdateListener(this);
53	
54	    transform = repeater.getTransform().createAnimation();
55	    transform.addAnimationsToLayer(layer);
56	    transform.addListener(this);
57	  }
