59	  @Override public void absorbContent(ListIterator<Content> contentsIter) {
60	    // This check prevents a repeater from getting added twice.
61	    // This can happen in the following situation:
62	    //    RECTANGLE
63	    //    REPEATER 1
64	    //    FILL
65	    //    REPEATER 2
66	    // In this case, the expected structure would be:
67	    //     REPEATER 2
68	    //        REPEATER 1
69	    //            RECTANGLE
70	    //        FILL
71	    // Without this check, REPEATER 1 will try and absorb contents once it is already inside of
72	    // REPEATER 2.
73	    if (contentGroup != null) {
74	      return;
75	    }
76	    // Fast forward the iterator until after this content.
77	    //noinspection StatementWithEmptyBody
78	    while (contentsIter.hasPrevious() && contentsIter.previous() != this) {
79	    }
80	    List<Content> contents = new ArrayList<>();
81	    while (contentsIter.hasPrevious()) {
82	      contents.add(contentsIter.previous());
83	      contentsIter.remove();
84	    }
85	    Collections.reverse(contents);
86	    contentGroup = new ContentGroup(lottieDrawable, layer, "Repeater", hidden, contents, null);
87	  }
