97	  @Override public Path getPath() {
98	    Path contentPath = contentGroup.getPath();
99	    path.reset();
100	    float copies = this.copies.getValue();
101	    float offset = this.offset.getValue();
102	    for (int i = (int) copies - 1; i >= 0; i--) {
103	      matrix.set(transform.getMatrixForRepeater(i + offset));
104	      path.addPath(contentPath, matrix);
105	    }
106	    return path;
107	  }
