22	public class RectangleContent
23	    implements BaseKeyframeAnimation.AnimationListener, KeyPathElementContent, PathContent {
24	  private final Path path = new Path();
25	  private final RectF rect = new RectF();
26	
27	  private final String name;
28	  private final boolean hidden;
29	  private final LottieDrawable lottieDrawable;
30	  private final BaseKeyframeAnimation<?, PointF> positionAnimation;
31	  private final BaseKeyframeAnimation<?, PointF> sizeAnimation;
32	  private final BaseKeyframeAnimation<?, Float> cornerRadiusAnimation;
33	
34	  private final CompoundTrimPathContent trimPaths = new CompoundTrimPathContent();
35	  /** This corner radius is from a layer item. The first one is from the roundedness on this specific rect. */
36	  @Nullable private BaseKeyframeAnimation<Float, Float> roundedCornersAnimation = null;
37	  private boolean isPathValid;
38	
39	  public RectangleContent(LottieDrawable lottieDrawable, BaseLayer layer, RectangleShape rectShape) {
40	    name = rectShape.getName();
41	    hidden = rectShape.isHidden();
42	    this.lottieDrawable = lottieDrawable;
43	    positionAnimation = rectShape.getPosition().createAnimation();
44	    sizeAnimation = rectShape.getSize().createAnimation();
45	    cornerRadiusAnimation = rectShape.getCornerRadius().createAnimation();
46	
47	    layer.addAnimation(positionAnimation);
48	    layer.addAnimation(sizeAnimation);
49	    layer.addAnimation(cornerRadiusAnimation);
50	
51	    positionAnimation.addUpdateListener(this);
52	    sizeAnimation.addUpdateListener(this);
53	    cornerRadiusAnimation.addUpdateListener(this);
54	  }
55	
56	  @Override
57	  public String getName() {
58	    return name;
59	  }
60	
