66	  private void invalidate() {
67	    isPathValid = false;
68	    lottieDrawable.invalidateSelf();
69	  }
70	
71	  @Override
72	  public void setContents(List<Content> contentsBefore, List<Content> contentsAfter) {
73	    for (Content content : contentsBefore) {
74	      if (content instanceof TrimPathContent &&
75	          ((TrimPathContent) content).getType() == ShapeTrimPath.Type.SIMULTANEOUSLY) {
76	        TrimPathContent trimPath = (TrimPathContent) content;
77	        trimPaths.addTrimPath(trimPath);
78	        trimPath.addListener(this);
79	      } else if (content instanceof RoundedCornersContent) {
80	        roundedCornersAnimation = ((RoundedCornersContent) content).getRoundedCorners();
81	      }
82	    }
83	  }
84	
85	  @Override
86	  public Path getPath() {
87	    if (isPathValid) {
88	      return path;
89	    }
90	
91	    path.reset();
92	
93	    if (hidden) {
94	      isPathValid = true;
95	      return path;
96	    }
97	
98	    PointF size = sizeAnimation.getValue();
99	    float halfWidth = size.x / 2f;
100	    float halfHeight = size.y / 2f;
101	    float radius = cornerRadiusAnimation == null ?
102	        0f : ((FloatKeyframeAnimation) cornerRadiusAnimation).getFloatValue();
103	    if (radius == 0f && this.roundedCornersAnimation != null) {
104	      radius = Math.min(roundedCornersAnimation.getValue(), Math.min(halfWidth, halfHeight));
105	    }
106	    float maxRadius = Math.min(halfWidth, halfHeight);
107	    if (radius > maxRadius) {
108	      radius = maxRadius;
109	    }
110	
111	    // Draw the rectangle top right to bottom left.
112	    PointF position = positionAnimation.getValue();
113	
114	    path.moveTo(position.x + halfWidth, position.y - halfHeight + radius);
115	
116	    path.lineTo(position.x + halfWidth, position.y + halfHeight - radius);
117	
118	    if (radius > 0) {
119	      rect.set(position.x + halfWidth - 2 * radius,
120	          position.y + halfHeight - 2 * radius,
121	          position.x + halfWidth,
122	          position.y + halfHeight);
123	      path.arcTo(rect, 0, 90, false);
124	    }
125	
126	    path.lineTo(position.x - halfWidth + radius, position.y + halfHeight);
127	
128	    if (radius > 0) {
129	      rect.set(position.x - halfWidth,
130	          position.y + halfHeight - 2 * radius,
131	          position.x - halfWidth + 2 * radius,
132	          position.y + halfHeight);
133	      path.arcTo(rect, 90, 90, false);
134	    }
135	
136	    path.lineTo(position.x - halfWidth, position.y - halfHeight + radius);
137	
138	    if (radius > 0) {
139	      rect.set(position.x - halfWidth,
140	          position.y - halfHeight,
141	          position.x - halfWidth + 2 * radius,
142	          position.y - halfHeight + 2 * radius);
143	      path.arcTo(rect, 180, 90, false);
144	    }
145	
146	    path.lineTo(position.x + halfWidth - radius, position.y - halfHeight);
147	
148	    if (radius > 0) {
149	      rect.set(position.x + halfWidth - 2 * radius,
150	          position.y - halfHeight,
151	          position.x + halfWidth,
152	          position.y - halfHeight + 2 * radius);
153	      path.arcTo(rect, 270, 90, false);
154	    }
155	    path.close();
156	
157	    trimPaths.apply(path);
158	
159	    isPathValid = true;
160	    return path;
161	  }
162	
163	  @Override
164	  public void resolveKeyPath(KeyPath keyPath, int depth, List<KeyPath> accumulator,
165	      KeyPath currentPartialKeyPath) {
166	    MiscUtils.resolveKeyPath(keyPath, depth, accumulator, currentPartialKeyPath, this);
167	  }
168	
169	  @Override
170	  public <T> void addValueCallback(T property, @Nullable LottieValueCallback<T> callback) {
171	    if (property == LottieProperty.RECTANGLE_SIZE) {
172	      sizeAnimation.setValueCallback((LottieValueCallback<PointF>) callback);
173	    } else if (property == LottieProperty.POSITION) {
174	      positionAnimation.setValueCallback((LottieValueCallback<PointF>) callback);
175	    } else if (property == LottieProperty.CORNER_RADIUS) {
176	      cornerRadiusAnimation.setValueCallback((LottieValueCallback<Float>) callback);
177	    }
178	  }
