    float fillAlpha = opacityAnimation.getValue() / 100f;
    int alpha = (int) (parentAlpha * fillAlpha);
    alpha = clamp(alpha, 0, 255);
    paint.setAlpha(alpha);

    if (shadowToApply != null) {
