236	          } else {
237	            cp1 = JsonUtils.jsonToPoint(reader, scale);
238	          }
239	          break;
240	        case 4: // i
241	          if (reader.peek() == JsonReader.Token.BEGIN_OBJECT) {
242	            reader.beginObject();
243	            float xCp2x = 0f;
244	            float xCp2y = 0f;
245	            float yCp2x = 0f;
246	            float yCp2y = 0f;
247	            while (reader.hasNext()) {
248	              switch (reader.selectName(INTERPOLATOR_NAMES)) {
249	                case 0: // x
250	                  if (reader.peek() == JsonReader.Token.NUMBER) {
251	                    xCp2x = (float) reader.nextDouble();
252	                    yCp2x = xCp2x;
253	                  } else {
254	                    reader.beginArray();
255	                    xCp2x = (float) reader.nextDouble();
256	                    if (reader.peek() == JsonReader.Token.NUMBER) {
257	                      yCp2x = (float) reader.nextDouble();
258	                    } else {
259	                      yCp2x = xCp2x;
260	                    }
261	                    reader.endArray();
262	                  }
263	                  break;
264	                case 1: // y
