1	package com.airbnb.lottie.animation.keyframe;
2	
3	import android.annotation.SuppressLint;
4	import androidx.annotation.FloatRange;
5	import androidx.annotation.NonNull;
6	import androidx.annotation.Nullable;
7	
8	import com.airbnb.lottie.L;
9	import com.airbnb.lottie.value.Keyframe;
10	import com.airbnb.lottie.value.LottieValueCallback;
11	
12	import java.util.ArrayList;
13	import java.util.List;
14	
15	/**
16	 * @param <K> Keyframe type
17	 * @param <A> Animation type
18	 */
19	public abstract class BaseKeyframeAnimation<K, A> {
20	
21	  public interface AnimationListener {
22	
23	    void onValueChanged();
24	  }
25	
26	  // This is not a Set because we don't want to create an iterator object on every setProgress.
27	  final List<AnimationListener> listeners = new ArrayList<>(1);
28	  private boolean isDiscrete = false;
29	
30	  private final KeyframesWrapper<K> keyframesWrapper;
31	  protected float progress = 0f;
32	  @Nullable protected LottieValueCallback<A> valueCallback;
33	
34	  @Nullable private A cachedGetValue = null;
35	
36	  private float cachedStartDelayProgress = -1f;
37	  private float cachedEndProgress = -1f;
38	
39	  BaseKeyframeAnimation(List<? extends Keyframe<K>> keyframes) {
40	    keyframesWrapper = wrap(keyframes);
41	  }
42	
43	  public void setIsDiscrete() {
44	    isDiscrete = true;
45	  }
46	
47	  public void addUpdateListener(AnimationListener listener) {
48	    listeners.add(listener);
49	  }
50	
51	  public void setProgress(@FloatRange(from = 0f, to = 1f) float progress) {
52	    if (L.isTraceEnabled()) {
53	      L.beginSection("BaseKeyframeAnimation#setProgress");
54	    }
55	    if (keyframesWrapper.isEmpty()) {
56	      if (L.isTraceEnabled()) {
57	        L.endSection("BaseKeyframeAnimation#setProgress");
58	      }
59	      return;
60	    }
61	    if (progress < getStartDelayProgress()) {
62	      progress = getStartDelayProgress();
63	    } else if (progress > getEndProgress()) {
64	      progress = getEndProgress();
65	    }
66	
67	    if (progress == this.progress) {
68	      if (L.isTraceEnabled()) {
69	        L.endSection("BaseKeyframeAnimation#setProgress");
70	      }
71	      return;
72	    }
73	    this.progress = progress;
74	    if (keyframesWrapper.isValueChanged(progress)) {
75	      notifyListeners();
76	    }
77	    if (L.isTraceEnabled()) {
78	      L.endSection("BaseKeyframeAnimation#setProgress");
79	    }
80	  }
81	
82	  public void notifyListeners() {
83	    if (L.isTraceEnabled()) {
84	      L.beginSection("BaseKeyframeAnimation#notifyListeners");
85	    }
86	    for (int i = 0; i < listeners.size(); i++) {
87	      listeners.get(i).onValueChanged();
88	    }
89	    if (L.isTraceEnabled()) {
90	      L.endSection("BaseKeyframeAnimation#notifyListeners");
91	    }
92	  }
93	
94	  protected Keyframe<K> getCurrentKeyframe() {
95	    if (L.isTraceEnabled()) {
96	      L.beginSection("BaseKeyframeAnimation#getCurrentKeyframe");
97	    }
98	    final Keyframe<K> keyframe = keyframesWrapper.getCurrentKeyframe();
99	    if (L.isTraceEnabled()) {
100	      L.endSection("BaseKeyframeAnimation#getCurrentKeyframe");
101	    }
102	    return keyframe;
103	  }
104	
105	  /**
106	   * Returns the progress into the current keyframe between 0 and 1. This does not take into account
107	   * any interpolation that the keyframe may have.
108	   */
109	  float getLinearCurrentKeyframeProgress() {
110	    if (isDiscrete) {
111	      return 0f;
112	    }
113	
114	    Keyframe<K> keyframe = getCurrentKeyframe();
115	    if (keyframe.isStatic()) {
116	      return 0f;
117	    }
118	    float progressIntoFrame = progress - keyframe.getStartProgress();
119	    float keyframeProgress = keyframe.getEndProgress() - keyframe.getStartProgress();
120	    return progressIntoFrame / keyframeProgress;
121	  }
122	
123	  /**
124	   * Takes the value of {@link #getLinearCurrentKeyframeProgress()} and interpolates it with
125	   * the current keyframe's interpolator.
126	   */
127	  protected float getInterpolatedCurrentKeyframeProgress() {
128	    Keyframe<K> keyframe = getCurrentKeyframe();
129	    // Keyframe should not be null here but there seems to be a Xiaomi Android 10 specific crash.
130	    // https://github.com/airbnb/lottie-android/issues/2050
131	    // https://github.com/airbnb/lottie-android/issues/2483
132	    if (keyframe == null || keyframe.isStatic() || keyframe.interpolator == null) {
133	      return 0f;
134	    }
135	    //noinspection ConstantConditions
136	    return keyframe.interpolator.getInterpolation(getLinearCurrentKeyframeProgress());
137	  }
138	
139	  @SuppressLint("Range")
140	  @FloatRange(from = 0f, to = 1f)
141	  private float getStartDelayProgress() {
142	    if (cachedStartDelayProgress == -1f) {
143	      cachedStartDelayProgress = keyframesWrapper.getStartDelayProgress();
144	    }
145	    return cachedStartDelayProgress;
146	  }
147	
148	  @SuppressLint("Range")
149	  @FloatRange(from = 0f, to = 1f)
150	  float getEndProgress() {
151	    if (cachedEndProgress == -1f) {
152	      cachedEndProgress = keyframesWrapper.getEndProgress();
153	    }
154	    return cachedEndProgress;
155	  }
156	
157	  public A getValue() {
158	    A value;
159	
160	    float linearProgress = getLinearCurrentKeyframeProgress();
161	    if (valueCallback == null && keyframesWrapper.isCachedValueEnabled(linearProgress) && !skipCache()) {
162	      return cachedGetValue;
163	    }
164	    final Keyframe<K> keyframe = getCurrentKeyframe();
165	
166	    if (keyframe.xInterpolator != null && keyframe.yInterpolator != null) {
167	      float xProgress = keyframe.xInterpolator.getInterpolation(linearProgress);
168	      float yProgress = keyframe.yInterpolator.getInterpolation(linearProgress);
169	      value = getValue(keyframe, linearProgress, xProgress, yProgress);
170	    } else {
171	      float progress = getInterpolatedCurrentKeyframeProgress();
172	      value = getValue(keyframe, progress);
173	    }
174	
175	    cachedGetValue = value;
176	    return value;
177	  }
178	
179	  protected boolean skipCache() {
180	    return false;
181	  }
182	
183	  public float getProgress() {
184	    return progress;
185	  }
186	
