219	  public Matrix getMatrix() {
220	    matrix.reset();
221	
222	    // Early exit: Check if 3D transformation is needed (avoid getValue() calls if null)
223	    boolean has3DRotation = (rotationX != null && rotationX.getFloatValue() != 0f) ||
224	                            (rotationY != null && rotationY.getFloatValue() != 0f) ||
225	                            (rotationZ != null && rotationZ.getFloatValue() != 0f);
226	
227	    // If there is 3D rotation, use the new Transform3D utility class
228	    if (has3DRotation) {
229	      float rotX = rotationX != null ? rotationX.getFloatValue() : 0f;
230	      float rotY = rotationY != null ? rotationY.getFloatValue() : 0f;
231	      float rotZ = rotationZ != null ? rotationZ.getFloatValue() : 0f;
232	
233	      // Update cache if values changed (Float.NaN initial values ensure first-call recalculation)
234	      if (rotX != cachedRotationX || rotY != cachedRotationY || rotZ != cachedRotationZ) {
235	        cachedRotationX = rotX;
236	        cachedRotationY = rotY;
237	        cachedRotationZ = rotZ;
238	        cachedCosX = rotX != 0f ? (float) Math.cos(Math.toRadians(rotX)) : 1f;
239	        cachedCosY = rotY != 0f ? (float) Math.cos(Math.toRadians(rotY)) : 1f;
240	      }
241	
242	      PointF anchorPointValue = anchorPoint == null ? null : anchorPoint.getValue();
243	      PointF positionValue = position == null ? null : position.getValue();
244	      ScaleXY scaleValue = scale == null ? null : scale.getValue();
245	
246	      // Extract scale values (default 1f, consistent with original code)
247	      float scaleX = scaleValue != null ? scaleValue.getScaleX() : 1f;
248	      float scaleY = scaleValue != null ? scaleValue.getScaleY() : 1f;
249	
250	      // Use Transform3D to calculate complete 3D transformation with cached cos values
251	      Transform3D.applyTransform(
252	        matrix,
253	        anchorPointValue,
254	        positionValue,
255	        scaleX,
256	        scaleY,
257	        rotX,
258	        rotY,
259	        rotZ,
260	        cachedCosX,
261	        cachedCosY
262	      );
263	
264	      return matrix;
265	    }
266	    BaseKeyframeAnimation<?, PointF> position = this.position;
267	    if (position != null) {
268	      PointF positionValue = position.getValue();
269	      if (positionValue != null && (positionValue.x != 0 || positionValue.y != 0)) {
270	        matrix.preTranslate(positionValue.x, positionValue.y);
271	      }
272	    }
273	
274	    // If autoOrient is true, the rotation should follow the derivative of the position rather
275	    // than the rotation property.
276	    if (autoOrient) {
277	      if (position != null) {
278	        float currentProgress = position.getProgress();
279	        PointF startPosition = position.getValue();
280	        // Store the start X and Y values because the pointF will be overwritten by the next getValue call.
281	        float startX = startPosition.x;
282	        float startY = startPosition.y;
283	        // 1) Find the next position value.
284	        // 2) Create a vector from the current position to the next position.
285	        // 3) Find the angle of that vector to the X axis (0 degrees).
286	        position.setProgress(currentProgress + 0.0001f);
287	        PointF nextPosition = position.getValue();
288	        position.setProgress(currentProgress);
289	        double rotationValue = Math.toDegrees(Math.atan2(nextPosition.y - startY, nextPosition.x - startX));
290	        matrix.preRotate((float) rotationValue);
291	      }
292	    } else {
293	      BaseKeyframeAnimation<Float, Float> rotation = this.rotation;
294	      if (rotation != null) {
295	        float rotationValue;
296	        if (rotation instanceof ValueCallbackKeyframeAnimation) {
297	          rotationValue = rotation.getValue();
298	        } else {
299	          rotationValue = ((FloatKeyframeAnimation) rotation).getFloatValue();
300	        }
301	        if (rotationValue != 0f) {
302	          matrix.preRotate(rotationValue);
303	        }
304	      }
305	    }
306	
307	    FloatKeyframeAnimation skew = this.skew;
308	    if (skew != null) {
309	      float mCos = skewAngle == null ? 0f : (float) Math.cos(Math.toRadians(-skewAngle.getFloatValue() + 90));
310	      float mSin = skewAngle == null ? 1f : (float) Math.sin(Math.toRadians(-skewAngle.getFloatValue() + 90));
311	      float aTan = (float) Math.tan(Math.toRadians(skew.getFloatValue()));
312	      clearSkewValues();
313	      skewValues[0] = mCos;
314	      skewValues[1] = mSin;
315	      skewValues[3] = -mSin;
316	      skewValues[4] = mCos;
317	      skewValues[8] = 1f;
318	      skewMatrix1.setValues(skewValues);
319	      clearSkewValues();
320	      skewValues[0] = 1f;
321	      skewValues[3] = aTan;
322	      skewValues[4] = 1f;
323	      skewValues[8] = 1f;
324	      skewMatrix2.setValues(skewValues);
325	      clearSkewValues();
326	      skewValues[0] = mCos;
327	      skewValues[1] = -mSin;
328	      skewValues[3] = mSin;
329	      skewValues[4] = mCos;
330	      skewValues[8] = 1;
331	      skewMatrix3.setValues(skewValues);
332	      skewMatrix2.preConcat(skewMatrix1);
333	      skewMatrix3.preConcat(skewMatrix2);
334	
335	      matrix.preConcat(skewMatrix3);
336	    }
337	
338	    BaseKeyframeAnimation<ScaleXY, ScaleXY> scale = this.scale;
339	    if (scale != null) {
340	      ScaleXY scaleTransform = scale.getValue();
341	      if (scaleTransform != null && (scaleTransform.getScaleX() != 1f || scaleTransform.getScaleY() != 1f)) {
342	        matrix.preScale(scaleTransform.getScaleX(), scaleTransform.getScaleY());
343	      }
344	    }
345	
346	    BaseKeyframeAnimation<PointF, PointF> anchorPoint = this.anchorPoint;
347	    if (anchorPoint != null) {
348	      PointF anchorPointValue = anchorPoint.getValue();
349	      if (anchorPointValue != null && (anchorPointValue.x != 0 || anchorPointValue.y != 0)) {
350	        matrix.preTranslate(-anchorPointValue.x, -anchorPointValue.y);
351	      }
352	    }
353	
354	    return matrix;
355	  }
356	
357	  private void clearSkewValues() {
358	    Arrays.fill(skewValues, 0f);
359	  }
360	
361	  /**
362	   * Get transformation matrix for repeater content.
363	   * This method applies transformations scaled by the amount parameter.
364	   *
365	   * @param amount Scaling factor for all transformations (based on copy index + offset)
366	   */
367	  public Matrix getMatrixForRepeater(float amount) {
368	    PointF position = this.position == null ? null : this.position.getValue();
369	    ScaleXY scale = this.scale == null ? null : this.scale.getValue();
370	    PointF anchorPoint = this.anchorPoint == null ? null : this.anchorPoint.getValue();
371	
372	    matrix.reset();
373	
374	    // 1. Apply position transformation
375	    if (position != null) {
376	      matrix.preTranslate(position.x * amount, position.y * amount);
377	    }
378	
379	    // 2. Apply rotation transformations
380	    // Check for 3D rotation
381	    float rotX = rotationX != null ? rotationX.getFloatValue() * amount : 0f;
382	    float rotY = rotationY != null ? rotationY.getFloatValue() * amount : 0f;
383	    float rotZ = rotationZ != null ? rotationZ.getFloatValue() * amount : 0f;
384	
385	    boolean has3DRotation = rotX != 0f || rotY != 0f || rotZ != 0f;
386	
387	    if (has3DRotation) {
388	      // Pre-compute cosine values once for this call
389	      float cosX = rotX != 0f ? (float) Math.cos(Math.toRadians(rotX)) : 1f;
390	      float cosY = rotY != 0f ? (float) Math.cos(Math.toRadians(rotY)) : 1f;
391	
392	      // Apply Z-axis rotation around anchor point
393	      if (rotZ != 0f) {
394	        matrix.preRotate(rotZ, anchorPoint == null ? 0f : anchorPoint.x, anchorPoint == null ? 0f : anchorPoint.y);
395	      }
396	
397	      // Apply 3D rotations using Transform3D utility (X and Y only, as Z was already applied)
398	      Transform3D.apply3DRotations(matrix, rotX, rotY, 0f, cosX, cosY);
399	    } else if (this.rotation != null) {
400	      // Fall back to 2D rotation
401	      float rotation = this.rotation.getValue();
402	      matrix.preRotate(rotation * amount, anchorPoint == null ? 0f : anchorPoint.x, anchorPoint == null ? 0f : anchorPoint.y);
403	    }
404	
405	    // 3. Apply scale transformation
406	    if (scale != null) {
407	      matrix.preScale(
408	          (float) Math.pow(scale.getScaleX(), amount),
409	          (float) Math.pow(scale.getScaleY(), amount));
410	    }
411	
412	    return matrix;
413	  }
