1	package com.airbnb.lottie.parser;
2	
3	import android.graphics.Color;
4	
5	import com.airbnb.lottie.model.content.GradientColor;
6	import com.airbnb.lottie.parser.moshi.JsonReader;
7	import com.airbnb.lottie.utils.GammaEvaluator;
8	import com.airbnb.lottie.utils.MiscUtils;
9	
10	import java.io.IOException;
11	import java.util.ArrayList;
12	import java.util.Arrays;
13	import java.util.List;
14	
15	public class GradientColorParser implements com.airbnb.lottie.parser.ValueParser<GradientColor> {
16	  /**
17	   * The number of colors if it exists in the json or -1 if it doesn't (legacy bodymovin)
18	   */
19	  private int colorPoints;
20	
21	  public GradientColorParser(int colorPoints) {
22	    this.colorPoints = colorPoints;
23	  }
24	
25	  /**
26	   * Both the color stops and opacity stops are in the same array.
27	   * There are {@link #colorPoints} colors sequentially as:
28	   * [
29	   * ...,
30	   * position,
31	   * red,
32	   * green,
33	   * blue,
34	   * ...
35	   * ]
36	   * <p>
37	   * The remainder of the array is the opacity stops sequentially as:
38	   * [
39	   * ...,
40	   * position,
41	   * opacity,
42	   * ...
43	   * ]
44	   */
45	  @Override
46	  public GradientColor parse(JsonReader reader, float scale)
47	      throws IOException {
48	    List<Float> array = new ArrayList<>();
49	    // The array was started by Keyframe because it thought that this may be an array of keyframes
50	    // but peek returned a number so it considered it a static array of numbers.
51	    boolean isArray = reader.peek() == JsonReader.Token.BEGIN_ARRAY;
52	    if (isArray) {
53	      reader.beginArray();
54	    }
55	    while (reader.hasNext()) {
56	      array.add((float) reader.nextDouble());
57	    }
58	    if (array.size() == 4 && array.get(0) == 1f) {
59	      // If a gradient color only contains one color at position 1, add a second stop with the same
60	      // color at position 0. Android's LinearGradient shader requires at least two colors.
61	      // https://github.com/airbnb/lottie-android/issues/1967
62	      array.set(0, 0f);
63	      array.add(1f);
64	      array.add(array.get(1));
65	      array.add(array.get(2));
66	      array.add(array.get(3));
67	      colorPoints = 2;
68	    }
69	    if (isArray) {
70	      reader.endArray();
71	    }
72	    if (colorPoints == -1) {
73	      colorPoints = array.size() / 4;
74	    }
75	
76	    float[] positions = new float[colorPoints];
77	    int[] colors = new int[colorPoints];
78	
79	    int r = 0;
80	    int g = 0;
81	    for (int i = 0; i < colorPoints * 4; i++) {
82	      int colorIndex = i / 4;
83	      double value = array.get(i);
84	      switch (i % 4) {
85	        case 0:
86	          // Positions should monotonically increase. If they don't, it can cause rendering problems on some phones.
87	          // https://github.com/airbnb/lottie-android/issues/1675
88	          if (colorIndex > 0 && positions[colorIndex - 1] >= (float) value) {
89	            positions[colorIndex] = (float) value + 0.01f;
90	          } else {
91	            positions[colorIndex] = (float) value;
92	          }
93	          break;
94	        case 1:
95	          r = (int) (value * 255);
96	          break;
97	        case 2:
98	          g = (int) (value * 255);
99	          break;
100	        case 3:
101	          int b = (int) (value * 255);
102	          colors[colorIndex] = Color.argb(255, r, g, b);
103	          break;
104	      }
105	    }
106	
107	    GradientColor gradientColor = new GradientColor(positions, colors);
108	    gradientColor = addOpacityStopsToGradientIfNeeded(gradientColor, array);
109	    return gradientColor;
110	  }
111	
112	  /**
113	   * This cheats a little bit.
114	   * Opacity stops can be at arbitrary intervals independent of color stops.
115	   * This uses the existing color stops and modifies the opacity at each existing color stop
116	   * based on what the opacity would be.
117	   * <p>
118	   * This should be a good approximation is nearly all cases. However, if there are many more
119	   * opacity stops than color stops, information will be lost.
120	   */
121	  private GradientColor addOpacityStopsToGradientIfNeeded(GradientColor gradientColor, List<Float> array) {
122	    int startIndex = colorPoints * 4;
123	    if (array.size() <= startIndex) {
124	      return gradientColor;
125	    }
126	
127	    // When there are opacity stops, we create a merged list of color stops and opacity stops.
128	    // For a given color stop, we linearly interpolate the opacity for the two opacity stops around it.
